-- 指标判定规则 rule + 指标定义 definition：conf_json 增量注入（与 detail-conf-init.sql 2026-10-14 版同源生成）
-- 用法：Doris 直接执行；幂等（JSON_SET 覆盖同名节点）；生效延迟 ≤ 5 分钟（引擎 TTL 缓存）

-- LICENSE
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库根目录（或 license 目录）下的 LICENSE 文件：是否有许可证、格式是否符合官方模板、版权年份和责任人是否填写正确、是否通过 OSI/FSF 开源认证。","formula":"阶梯计分（递进累加）：无许可证 0 → 有许可证 5 → 模板一致 +3（8 分）→ 版权正确 +1（9 分）→ OSI/FSF 认证 +1（10 分）；前置台阶未达成时，后续台阶不再评估","conditions":[{"label":"无 LICENSE 文件","value":"0 分（有效低分，不是不参评）"},{"label":"有许可证","value":"5 分（基础分）"},{"label":"格式符合官方模板","value":"+3 分 → 8 分"},{"label":"版权年份和责任人正确","value":"+1 分 → 9 分"},{"label":"通过 OSI/FSF 认证","value":"+1 分 → 10 分"}],"naCondition":"无，本指标恒有得分。","notes":[]},"definition":{"brief":"衡量仓库是否随源码发布了规范的开源许可证（LICENSE 文件），以及许可证的完整程度：格式是否符合官方模板、版权信息是否正确、是否通过权威开源认证。","purpose":"许可证是他人合法使用、修改与再分发代码的依据；缺失或不规范的许可证会让下游使用面临法律不确定性，也是开源合规的第一道门槛。","details":[{"label":"数据来源","value":"仓库文件树扫描（根目录或 license 目录的 LICENSE 文件，内容模板识别）"},{"label":"考察维度","value":"有无许可证 → 格式与官方模板一致性 → 版权年份与责任人 → OSI/FSF 认证"},{"label":"参考标准","value":"OSI 认证开源许可证清单、FSF 自由软件许可证清单"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库根目录（或 license 目录）下的 LICENSE 文件：是否有许可证、格式是否符合官方模板、版权年份和责任人是否填写正确、是否通过 OSI/FSF 开源认证。","formula":"阶梯计分（递进累加）：无许可证 0 → 有许可证 5 → 模板一致 +3（8 分）→ 版权正确 +1（9 分）→ OSI/FSF 认证 +1（10 分）；前置台阶未达成时，后续台阶不再评估","conditions":[{"label":"无 LICENSE 文件","value":"0 分（有效低分，不是不参评）"},{"label":"有许可证","value":"5 分（基础分）"},{"label":"格式符合官方模板","value":"+3 分 → 8 分"},{"label":"版权年份和责任人正确","value":"+1 分 → 9 分"},{"label":"通过 OSI/FSF 认证","value":"+1 分 → 10 分"}],"naCondition":"无，本指标恒有得分。","notes":[]},"definition":{"brief":"衡量仓库是否随源码发布了规范的开源许可证（LICENSE 文件），以及许可证的完整程度：格式是否符合官方模板、版权信息是否正确、是否通过权威开源认证。","purpose":"许可证是他人合法使用、修改与再分发代码的依据；缺失或不规范的许可证会让下游使用面临法律不确定性，也是开源合规的第一道门槛。","details":[{"label":"数据来源","value":"仓库文件树扫描（根目录或 license 目录的 LICENSE 文件，内容模板识别）"},{"label":"考察维度","value":"有无许可证 → 格式与官方模板一致性 → 版权年份与责任人 → OSI/FSF 认证"},{"label":"参考标准","value":"OSI 认证开源许可证清单、FSF 自由软件许可证清单"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'LICENSE';

-- COPYRIGHT
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"逐个检查源码文件（.go/.java/.py/.js/.c/.cpp/.rs/.ts/.sh/.bat，test/tests 目录除外）的文件头版权声明，是否与仓库 LICENSE 协议对应的官方版权模板一致。木兰协议的两行短头视为不合格。","formula":"得分 = 10 − 0.2 × 不合格文件数（最低 0 分，50 个扣完）","conditions":[{"label":"合格","value":"文件头含规范版权行（年份 + Huawei），且正文与模板匹配"},{"label":"不合格","value":"无文件头 / 无版权行 / 版权行不规范 / 正文与模板不匹配"},{"label":"比对模板","value":"按 LICENSE 类型自动确定：木兰协议 → 官方模板；带应用附录 → 印刷归一模板；其他 → 内置模板集"}],"naCondition":"仓库无 LICENSE 文件（或不可读）、或没有任何目标类型源码文件时，本指标不参评（不计入总分，不是 0 分）。","notes":["upstream banner（上游代码标识）仅标注展示、不影响判定","每个不合格文件的具体原因可在「版权合规问题文件清单」中查看"]},"definition":{"brief":"衡量仓库源码文件头的版权声明是否与 LICENSE 协议对应的官方版权模板一致，即「代码带着正确的版权头发布」。","purpose":"版权声明是权利主张的法律凭据；文件头缺失或不规范会削弱权利主张，也影响代码溯源与合规审计。","details":[{"label":"数据来源","value":"文件扫描脚本逐文件比对（结果存版权合规问题文件清单）"},{"label":"比对模板","value":"按 LICENSE 类型自动确定：木兰协议 → 官方模板；带应用附录 → 印刷归一模板；其他 → 内置模板集"},{"label":"检查范围","value":".go/.java/.py/.js/.c/.cpp/.rs/.ts/.sh/.bat 源码文件，test/tests 目录除外"}],"notes":["木兰协议的两行短头视为不合格"]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"逐个检查源码文件（.go/.java/.py/.js/.c/.cpp/.rs/.ts/.sh/.bat，test/tests 目录除外）的文件头版权声明，是否与仓库 LICENSE 协议对应的官方版权模板一致。木兰协议的两行短头视为不合格。","formula":"得分 = 10 − 0.2 × 不合格文件数（最低 0 分，50 个扣完）","conditions":[{"label":"合格","value":"文件头含规范版权行（年份 + Huawei），且正文与模板匹配"},{"label":"不合格","value":"无文件头 / 无版权行 / 版权行不规范 / 正文与模板不匹配"},{"label":"比对模板","value":"按 LICENSE 类型自动确定：木兰协议 → 官方模板；带应用附录 → 印刷归一模板；其他 → 内置模板集"}],"naCondition":"仓库无 LICENSE 文件（或不可读）、或没有任何目标类型源码文件时，本指标不参评（不计入总分，不是 0 分）。","notes":["upstream banner（上游代码标识）仅标注展示、不影响判定","每个不合格文件的具体原因可在「版权合规问题文件清单」中查看"]},"definition":{"brief":"衡量仓库源码文件头的版权声明是否与 LICENSE 协议对应的官方版权模板一致，即「代码带着正确的版权头发布」。","purpose":"版权声明是权利主张的法律凭据；文件头缺失或不规范会削弱权利主张，也影响代码溯源与合规审计。","details":[{"label":"数据来源","value":"文件扫描脚本逐文件比对（结果存版权合规问题文件清单）"},{"label":"比对模板","value":"按 LICENSE 类型自动确定：木兰协议 → 官方模板；带应用附录 → 印刷归一模板；其他 → 内置模板集"},{"label":"检查范围","value":".go/.java/.py/.js/.c/.cpp/.rs/.ts/.sh/.bat 源码文件，test/tests 目录除外"}],"notes":["木兰协议的两行短头视为不合格"]}}' AS JSON), '$.definition'))
WHERE metric_code = 'COPYRIGHT';

-- DANGEROUS_WF
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查 .gitcode/workflows 下 CI 配置文件中的两类危险写法：① 显式配置 allow-unsafe-pr-checkout: true（允许检出不可信的 PR 代码）；② 脚本步骤中直接引用不可信上下文变量（如 PR 标题、描述、评论内容，可被注入恶意命令）。","formula":"发现任意一处危险模式 = 0 分；全部干净 = 10 分","conditions":[{"label":"危险模式 1","value":"workflow 中存在 allow-unsafe-pr-checkout: true"},{"label":"危险模式 2","value":"步骤中直接使用 PR 标题 / 描述 / 评论内容等不可信上下文变量"}],"naCondition":"仓库没有 workflow 文件、或文件解析失败（结论不完整，不当 0 分处理）时，本指标不参评。","notes":[]},"definition":{"brief":"衡量 CI workflow 配置的安全水位：是否存在允许检出不可信 PR 代码、或在脚本中直接引用不可信上下文变量等危险写法。","purpose":"workflow 凭据权限高，恶意 PR 可借不可信输入注入命令窃取令牌，是开源供应链攻击的常见入口；本指标用于提前暴露这类可被利用的配置。","details":[{"label":"数据来源","value":".gitcode/workflows 目录 CI 配置文件扫描"},{"label":"检查对象","value":"allow-unsafe-pr-checkout 显式开启、脚本步骤中直接引用 PR 标题/描述/评论等不可信上下文变量"},{"label":"参考标准","value":"对齐 OSSF Scorecard dangerous-workflow 检查项"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查 .gitcode/workflows 下 CI 配置文件中的两类危险写法：① 显式配置 allow-unsafe-pr-checkout: true（允许检出不可信的 PR 代码）；② 脚本步骤中直接引用不可信上下文变量（如 PR 标题、描述、评论内容，可被注入恶意命令）。","formula":"发现任意一处危险模式 = 0 分；全部干净 = 10 分","conditions":[{"label":"危险模式 1","value":"workflow 中存在 allow-unsafe-pr-checkout: true"},{"label":"危险模式 2","value":"步骤中直接使用 PR 标题 / 描述 / 评论内容等不可信上下文变量"}],"naCondition":"仓库没有 workflow 文件、或文件解析失败（结论不完整，不当 0 分处理）时，本指标不参评。","notes":[]},"definition":{"brief":"衡量 CI workflow 配置的安全水位：是否存在允许检出不可信 PR 代码、或在脚本中直接引用不可信上下文变量等危险写法。","purpose":"workflow 凭据权限高，恶意 PR 可借不可信输入注入命令窃取令牌，是开源供应链攻击的常见入口；本指标用于提前暴露这类可被利用的配置。","details":[{"label":"数据来源","value":".gitcode/workflows 目录 CI 配置文件扫描"},{"label":"检查对象","value":"allow-unsafe-pr-checkout 显式开启、脚本步骤中直接引用 PR 标题/描述/评论等不可信上下文变量"},{"label":"参考标准","value":"对齐 OSSF Scorecard dangerous-workflow 检查项"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'DANGEROUS_WF';

-- TOKEN_PERM
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查 CI 中引用的插件（action）实际获得的权限，是否超出该插件正常工作所需的基准权限。未收录在基准表中的插件按只读基准检查。","formula":"得分 = 10 − 违规插件数（最低 0 分；同一插件多处引用只记一次）","conditions":[{"label":"权限生效顺序","value":"job 级配置 > 文件顶层配置 > 平台默认（读）"},{"label":"违规判定","value":"插件所在 job 的生效权限中任一项为写（write）且超出该插件基准"},{"label":"正确做法","value":"需要写权限的插件单独拆 job 配置，避免一个 job 全量开写"}],"naCondition":"无 workflow 文件、文件解析失败、或有 workflow 但没有引用任何插件（纯脚本/纯复用引用）时，本指标不参评。","notes":["读写分离：job 下多个插件共享同一权限，全 job 开写会让所有只读基准插件同时违规"]},"definition":{"brief":"衡量 CI 中引用的插件（action）实际获得的权限是否超出其正常工作所需，即「CI 权限是否遵循最小权限原则」。","purpose":"job 下多个插件共享同一套权限，全 job 开写会让所有只读基准插件同时暴露；权限越大，凭据泄露或插件被投毒时的影响面越大。","details":[{"label":"数据来源","value":"workflow 文件中的插件引用与权限配置（per-action 基准表比对）"},{"label":"权限生效顺序","value":"job 级配置 > 文件顶层配置 > 平台默认（只读）"},{"label":"基准口径","value":"未收录在基准表中的插件按只读基准检查"}],"notes":["需要写权限的插件应单独拆 job 配置，避免一个 job 全量开写"]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查 CI 中引用的插件（action）实际获得的权限，是否超出该插件正常工作所需的基准权限。未收录在基准表中的插件按只读基准检查。","formula":"得分 = 10 − 违规插件数（最低 0 分；同一插件多处引用只记一次）","conditions":[{"label":"权限生效顺序","value":"job 级配置 > 文件顶层配置 > 平台默认（读）"},{"label":"违规判定","value":"插件所在 job 的生效权限中任一项为写（write）且超出该插件基准"},{"label":"正确做法","value":"需要写权限的插件单独拆 job 配置，避免一个 job 全量开写"}],"naCondition":"无 workflow 文件、文件解析失败、或有 workflow 但没有引用任何插件（纯脚本/纯复用引用）时，本指标不参评。","notes":["读写分离：job 下多个插件共享同一权限，全 job 开写会让所有只读基准插件同时违规"]},"definition":{"brief":"衡量 CI 中引用的插件（action）实际获得的权限是否超出其正常工作所需，即「CI 权限是否遵循最小权限原则」。","purpose":"job 下多个插件共享同一套权限，全 job 开写会让所有只读基准插件同时暴露；权限越大，凭据泄露或插件被投毒时的影响面越大。","details":[{"label":"数据来源","value":"workflow 文件中的插件引用与权限配置（per-action 基准表比对）"},{"label":"权限生效顺序","value":"job 级配置 > 文件顶层配置 > 平台默认（只读）"},{"label":"基准口径","value":"未收录在基准表中的插件按只读基准检查"}],"notes":["需要写权限的插件应单独拆 job 配置，避免一个 job 全量开写"]}}' AS JSON), '$.definition'))
WHERE metric_code = 'TOKEN_PERM';

-- PINNED_DEP
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查 CI/CD 与构建文件中的依赖是否固定到不可变版本（gcheck 严格口径，对齐 OSSF Scorecard v5.5.0 pinned-dependencies）：容器镜像须以 @sha256 摘要引用、pip 安装须 --require-hashes、npm 须 npm ci 或固定哈希、go install / go get 须固定版本、下载即执行须按哈希固定。workflow action 引用默认不检测。","formula":"得分 = 已固定依赖数 / 依赖总数 × 10","conditions":[{"label":"已固定","value":"镜像 @sha256 摘要 / pip --require-hashes / npm ci / go 固定版本 / 下载固定到 40 位提交 SHA"},{"label":"未固定","value":"浮动 tag（如 latest）、仅版本号无哈希、可变分支引用"},{"label":"口径问题条目","value":"判定依据标注变量引用、裸名引用、构建阶段别名、本地路径等的条目没有可通过的整改路径，属口径问题，不开整改单"}],"naCondition":"未识别到任何依赖（not-applicable）、无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA，不计分子分母。","notes":["2026-10-09 起生产数据来自 security_gcheck_scan.py（gcheck 离线扫描批次）","workflow action 引用默认不检测（GitCode 平台不进行 actions 版本依赖扫描，官方插件裸名引用没有可固定的版本位）"]},"definition":{"brief":"衡量构建与 CI 流程中引用的外部依赖是否固定到不可变版本（哈希 / 摘要），即「供应链依赖是否可复现、防篡改」。","purpose":"浮动版本的依赖可被上游篡改或消失，导致构建不可重现；固定到 sha256 摘要等不可变引用可保证供应链完整性与构建可重现性。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据）"},{"label":"检查范围","value":"容器镜像、pip/npm/go/choco/nuget 命令、下载即执行等 7 项判据"},{"label":"参考标准","value":"OSSF Scorecard v5.5.0 pinned-dependencies"}],"notes":["workflow action 引用默认不检测（GitCode 平台不进行 actions 版本依赖扫描）"]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查 CI/CD 与构建文件中的依赖是否固定到不可变版本（gcheck 严格口径，对齐 OSSF Scorecard v5.5.0 pinned-dependencies）：容器镜像须以 @sha256 摘要引用、pip 安装须 --require-hashes、npm 须 npm ci 或固定哈希、go install / go get 须固定版本、下载即执行须按哈希固定。workflow action 引用默认不检测。","formula":"得分 = 已固定依赖数 / 依赖总数 × 10","conditions":[{"label":"已固定","value":"镜像 @sha256 摘要 / pip --require-hashes / npm ci / go 固定版本 / 下载固定到 40 位提交 SHA"},{"label":"未固定","value":"浮动 tag（如 latest）、仅版本号无哈希、可变分支引用"},{"label":"口径问题条目","value":"判定依据标注变量引用、裸名引用、构建阶段别名、本地路径等的条目没有可通过的整改路径，属口径问题，不开整改单"}],"naCondition":"未识别到任何依赖（not-applicable）、无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA，不计分子分母。","notes":["2026-10-09 起生产数据来自 security_gcheck_scan.py（gcheck 离线扫描批次）","workflow action 引用默认不检测（GitCode 平台不进行 actions 版本依赖扫描，官方插件裸名引用没有可固定的版本位）"]},"definition":{"brief":"衡量构建与 CI 流程中引用的外部依赖是否固定到不可变版本（哈希 / 摘要），即「供应链依赖是否可复现、防篡改」。","purpose":"浮动版本的依赖可被上游篡改或消失，导致构建不可重现；固定到 sha256 摘要等不可变引用可保证供应链完整性与构建可重现性。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据）"},{"label":"检查范围","value":"容器镜像、pip/npm/go/choco/nuget 命令、下载即执行等 7 项判据"},{"label":"参考标准","value":"OSSF Scorecard v5.5.0 pinned-dependencies"}],"notes":["workflow action 引用默认不检测（GitCode 平台不进行 actions 版本依赖扫描）"]}}' AS JSON), '$.definition'))
WHERE metric_code = 'PINNED_DEP';

-- BINARY_ARTIFACTS
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库中是否直接提交了二进制可执行产物（gcheck 严格口径：按文件内容魔数识别，不再按文件名后缀判定）。识别 ELF / PE / Mach-O / WASM 可执行与 ar 归档等真二进制。","formula":"得分 = 10 − 二进制文件数（最低 0 分，每个文件扣 1 分）","conditions":[{"label":"命中即扣分","value":"文件内容命中魔数特征（ELF / PE / Mach-O / WASM / ar 归档），不区分目录"}],"naCondition":"无，本指标恒有得分。","notes":["2026-10-09 口径切换：由文件名后缀清单改为文件内容魔数识别（gcheck binary-artifacts），历史批次数据不可比",".gz / .zip / .pdf / .jar / .pyc 等非可执行产物不再上报","vendor / node_modules 目录照报（上游口径）"]},"definition":{"brief":"衡量仓库是否直接提交了二进制可执行产物（按文件内容魔数识别，而非文件名后缀）。","purpose":"二进制产物无法进行代码评审、无法追踪来源与许可，是仓库投毒与许可污染的高风险载体。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据）"},{"label":"识别对象","value":"ELF / PE / Mach-O / WASM 可执行与 ar 归档等真二进制（文件内容魔数识别）"},{"label":"参考标准","value":"OSSF Scorecard binary-artifacts"}],"notes":["2026-10-09 口径切换：由文件名后缀清单改为文件内容魔数识别，历史批次数据不可比"]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库中是否直接提交了二进制可执行产物（gcheck 严格口径：按文件内容魔数识别，不再按文件名后缀判定）。识别 ELF / PE / Mach-O / WASM 可执行与 ar 归档等真二进制。","formula":"得分 = 10 − 二进制文件数（最低 0 分，每个文件扣 1 分）","conditions":[{"label":"命中即扣分","value":"文件内容命中魔数特征（ELF / PE / Mach-O / WASM / ar 归档），不区分目录"}],"naCondition":"无，本指标恒有得分。","notes":["2026-10-09 口径切换：由文件名后缀清单改为文件内容魔数识别（gcheck binary-artifacts），历史批次数据不可比",".gz / .zip / .pdf / .jar / .pyc 等非可执行产物不再上报","vendor / node_modules 目录照报（上游口径）"]},"definition":{"brief":"衡量仓库是否直接提交了二进制可执行产物（按文件内容魔数识别，而非文件名后缀）。","purpose":"二进制产物无法进行代码评审、无法追踪来源与许可，是仓库投毒与许可污染的高风险载体。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据）"},{"label":"识别对象","value":"ELF / PE / Mach-O / WASM 可执行与 ar 归档等真二进制（文件内容魔数识别）"},{"label":"参考标准","value":"OSSF Scorecard binary-artifacts"}],"notes":["2026-10-09 口径切换：由文件名后缀清单改为文件内容魔数识别，历史批次数据不可比"]}}' AS JSON), '$.definition'))
WHERE metric_code = 'BINARY_ARTIFACTS';

-- CODE_REVIEW
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查最近 30 次已合入 PR 中，每个 PR 是否存在有效评审：有「非机器人、非 PR 创建人」通过 /lgtm 或 /approve 命令给出认可。","formula":"得分 = 已评审 PR 数 / PR 总数 × 10","conditions":[{"label":"已评审","value":"存在非机器人、非创建人的 /lgtm 或 /approve 评论"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"剔除机器人创建的 PR 后数量为 0 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量近 30 次已合入 PR 是否经过有效人工评审：存在非机器人、非创建人给出的 /lgtm 或 /approve 认可。","purpose":"人工评审是代码质量与安全的最后一道人肉防线，未经评审的代码合入会放大缺陷与后门风险。","details":[{"label":"数据来源","value":"PR 评论扫描（/lgtm、/approve 命令）"},{"label":"统计口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"},{"label":"参考标准","value":"对齐 OSSF Scorecard code-review 思想"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查最近 30 次已合入 PR 中，每个 PR 是否存在有效评审：有「非机器人、非 PR 创建人」通过 /lgtm 或 /approve 命令给出认可。","formula":"得分 = 已评审 PR 数 / PR 总数 × 10","conditions":[{"label":"已评审","value":"存在非机器人、非创建人的 /lgtm 或 /approve 评论"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"剔除机器人创建的 PR 后数量为 0 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量近 30 次已合入 PR 是否经过有效人工评审：存在非机器人、非创建人给出的 /lgtm 或 /approve 认可。","purpose":"人工评审是代码质量与安全的最后一道人肉防线，未经评审的代码合入会放大缺陷与后门风险。","details":[{"label":"数据来源","value":"PR 评论扫描（/lgtm、/approve 命令）"},{"label":"统计口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"},{"label":"参考标准","value":"对齐 OSSF Scorecard code-review 思想"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'CODE_REVIEW';

-- BRANCH_PROTECTION
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"GitCode 平台已默认提供基础分支保护（分支锁定、强制走 PR、评审门槛），本指标主要考察进阶要求：是否通过 .infra_self_service/rebot.yaml 配置了双人 LGTM（lgtm_need_num=2）并真正落实。","formula":"二元计分：默认 8 分；配置 lgtm_need_num=2 且近 30 个已合入 PR 每个都有两条不同人的 /lgtm = 10 分；配置了但未通过仍 8 分（无中间分）","conditions":[{"label":"基础 8 分","value":"平台默认分支保护，恒定满足"},{"label":"满分 10 分","value":"rebot.yaml 配置 lgtm_need_num=2，且近 30 PR 每个都有两条来自不同人（剔除机器人和 PR 作者）的 /lgtm"}],"naCondition":"无，本指标恒有得分。","notes":["lgtm_need_num 取其他值（1/3/…）不触发双人检查，按默认 8 分"]},"definition":{"brief":"衡量仓库受保护分支的管控强度：平台默认管控基线之上，是否通过 rebot.yaml 配置了双人 LGTM 增强评审并真正落实。","purpose":"分支保护防止绕过评审直接 push；多人审批保证关键代码至少经两人把关，降低单点失误与恶意合入的风险。","details":[{"label":"数据来源","value":"平台分支保护配置 + .infra_self_service/rebot.yaml 配置扫描"},{"label":"统计口径","value":"近 30 个已合入 PR 的 /lgtm 评论（剔除机器人和 PR 作者）"},{"label":"评分结构","value":"平台默认管控基线 8 分 + rebot.yaml 双人 LGTM 增强满分 2 分"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"GitCode 平台已默认提供基础分支保护（分支锁定、强制走 PR、评审门槛），本指标主要考察进阶要求：是否通过 .infra_self_service/rebot.yaml 配置了双人 LGTM（lgtm_need_num=2）并真正落实。","formula":"二元计分：默认 8 分；配置 lgtm_need_num=2 且近 30 个已合入 PR 每个都有两条不同人的 /lgtm = 10 分；配置了但未通过仍 8 分（无中间分）","conditions":[{"label":"基础 8 分","value":"平台默认分支保护，恒定满足"},{"label":"满分 10 分","value":"rebot.yaml 配置 lgtm_need_num=2，且近 30 PR 每个都有两条来自不同人（剔除机器人和 PR 作者）的 /lgtm"}],"naCondition":"无，本指标恒有得分。","notes":["lgtm_need_num 取其他值（1/3/…）不触发双人检查，按默认 8 分"]},"definition":{"brief":"衡量仓库受保护分支的管控强度：平台默认管控基线之上，是否通过 rebot.yaml 配置了双人 LGTM 增强评审并真正落实。","purpose":"分支保护防止绕过评审直接 push；多人审批保证关键代码至少经两人把关，降低单点失误与恶意合入的风险。","details":[{"label":"数据来源","value":"平台分支保护配置 + .infra_self_service/rebot.yaml 配置扫描"},{"label":"统计口径","value":"近 30 个已合入 PR 的 /lgtm 评论（剔除机器人和 PR 作者）"},{"label":"评分结构","value":"平台默认管控基线 8 分 + rebot.yaml 双人 LGTM 增强满分 2 分"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'BRANCH_PROTECTION';

-- WEBHOOKS
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库活跃的 Webhook 中，有多少配置了密钥（secret）。未配密钥的 Webhook 请求可被伪造。","formula":"得分 = 10 × 配置密钥的 Webhook 数 / 活跃 Webhook 总数（向下取整）","conditions":[{"label":"已配密钥","value":"活跃（active）且密钥非空"},{"label":"无活跃钩子","value":"10 分（没有入口即没有风险，不是不参评）"},{"label":"全部未配","value":"0 分"}],"naCondition":"无，本指标恒有得分。","notes":[]},"definition":{"brief":"衡量仓库活跃 Webhook 中已配置密钥（secret）的比例：密钥缺失的接收端可被任何人伪造请求触发。","purpose":"未配密钥的 Webhook 请求无法验证来源，攻击者可伪造事件触发内部流程，导致敏感信息泄露或非授权操作。","details":[{"label":"数据来源","value":"平台 API 采集的 Webhook 配置"},{"label":"统计口径","value":"分母只计活跃（active=1）钩子，未激活与状态未知的不计入"},{"label":"判定","value":"已配置密钥 = password_is_null=0（采集层不落密码明文）"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库活跃的 Webhook 中，有多少配置了密钥（secret）。未配密钥的 Webhook 请求可被伪造。","formula":"得分 = 10 × 配置密钥的 Webhook 数 / 活跃 Webhook 总数（向下取整）","conditions":[{"label":"已配密钥","value":"活跃（active）且密钥非空"},{"label":"无活跃钩子","value":"10 分（没有入口即没有风险，不是不参评）"},{"label":"全部未配","value":"0 分"}],"naCondition":"无，本指标恒有得分。","notes":[]},"definition":{"brief":"衡量仓库活跃 Webhook 中已配置密钥（secret）的比例：密钥缺失的接收端可被任何人伪造请求触发。","purpose":"未配密钥的 Webhook 请求无法验证来源，攻击者可伪造事件触发内部流程，导致敏感信息泄露或非授权操作。","details":[{"label":"数据来源","value":"平台 API 采集的 Webhook 配置"},{"label":"统计口径","value":"分母只计活跃（active=1）钩子，未激活与状态未知的不计入"},{"label":"判定","value":"已配置密钥 = password_is_null=0（采集层不落密码明文）"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'WEBHOOKS';

-- CI_TESTS
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查最近 30 次已合入 PR（与代码评审同口径）中，每个 PR 是否有 CI 流水线执行记录——只要触发过流水线即视为有 CI。","formula":"得分 = 10 × 有 CI 的 PR 数 / PR 总数","conditions":[{"label":"有 CI","value":"PR 关联到流水线执行记录（CodeArts 关联表）"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"仓库无已合入 PR 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量近 30 次已合入 PR 是否有 CI 流水线执行记录：代码合入前是否经过自动化构建与测试把关。","purpose":"无 CI 把关的 PR 缺陷可直接进入主干，回归风险不可控；CI 覆盖率反映工程化质量水位。","details":[{"label":"数据来源","value":"PR 与流水线执行记录关联（CodeArts 关联表）"},{"label":"统计口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"notes":["只要触发过流水线即视为有 CI，不考察流水线结果成败"]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查最近 30 次已合入 PR（与代码评审同口径）中，每个 PR 是否有 CI 流水线执行记录——只要触发过流水线即视为有 CI。","formula":"得分 = 10 × 有 CI 的 PR 数 / PR 总数","conditions":[{"label":"有 CI","value":"PR 关联到流水线执行记录（CodeArts 关联表）"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"仓库无已合入 PR 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量近 30 次已合入 PR 是否有 CI 流水线执行记录：代码合入前是否经过自动化构建与测试把关。","purpose":"无 CI 把关的 PR 缺陷可直接进入主干，回归风险不可控；CI 覆盖率反映工程化质量水位。","details":[{"label":"数据来源","value":"PR 与流水线执行记录关联（CodeArts 关联表）"},{"label":"统计口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"notes":["只要触发过流水线即视为有 CI，不考察流水线结果成败"]}}' AS JSON), '$.definition'))
WHERE metric_code = 'CI_TESTS';

-- SIGNED_RELEASES
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查最近 30 个 Release 版本（含预发布，忽略纯源码包版本）的附件中，是否同时包含 sha256 校验文件和数字签名文件。","formula":"全部版本均同时含 sha256 校验文件与签名文件 = 10 分；任一版本缺少任一项 = 0 分（一票否决）","conditions":[{"label":"sha256 校验文件","value":".sha256 / .sha256sum"},{"label":"数字签名资产","value":".asc / .sig / .pgp / .gpg / .minisig / .pem / .crt / .cer / .p7s"}],"naCondition":"仓库没有任何 Release 时，本指标不参评（不计入总分，不是 0 分）。","notes":["2026-10-20 口径调整：sha256 与签名须同时存在（AND），移除 SLSA Provenance 等效判定"]},"definition":{"brief":"衡量最近 30 个版本是否同时提供 sha256 校验文件与数字签名文件：发布物能否被验证完整性与来源。","purpose":"版本签名让使用者可验证下载内容未被篡改、确实来自官方构建，防止被投毒的发行包流入下游；sha256 校验文件用于下载完整性校验。","details":[{"label":"数据来源","value":"平台 Release 资产扫描"},{"label":"统计口径","value":"最近 30 个版本（含预发布）；仅有源码包（source only）的版本按上游口径忽略"},{"label":"判定","value":"sha256 校验文件（.sha256/.sha256sum）与数字签名资产（.asc/.sig/.pgp 等）均须存在，缺一即不满足"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查最近 30 个 Release 版本（含预发布，忽略纯源码包版本）的附件中，是否同时包含 sha256 校验文件和数字签名文件。","formula":"全部版本均同时含 sha256 校验文件与签名文件 = 10 分；任一版本缺少任一项 = 0 分（一票否决）","conditions":[{"label":"sha256 校验文件","value":".sha256 / .sha256sum"},{"label":"数字签名资产","value":".asc / .sig / .pgp / .gpg / .minisig / .pem / .crt / .cer / .p7s"}],"naCondition":"仓库没有任何 Release 时，本指标不参评（不计入总分，不是 0 分）。","notes":["2026-10-20 口径调整：sha256 与签名须同时存在（AND），移除 SLSA Provenance 等效判定"]},"definition":{"brief":"衡量最近 30 个版本是否同时提供 sha256 校验文件与数字签名文件：发布物能否被验证完整性与来源。","purpose":"版本签名让使用者可验证下载内容未被篡改、确实来自官方构建，防止被投毒的发行包流入下游；sha256 校验文件用于下载完整性校验。","details":[{"label":"数据来源","value":"平台 Release 资产扫描"},{"label":"统计口径","value":"最近 30 个版本（含预发布）；仅有源码包（source only）的版本按上游口径忽略"},{"label":"判定","value":"sha256 校验文件（.sha256/.sha256sum）与数字签名资产（.asc/.sig/.pgp 等）均须存在，缺一即不满足"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'SIGNED_RELEASES';

-- PACKAGING
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库是否具备自动化发包能力，满足任一即算：workflow 中配置了制品上传插件（obs-upload 或 upload-artifact）；或仓库被收录在 openEuler（Eluermaker）打包工程清单中。","formula":"具备自动化发包能力 = 10 分；未检出 = 0 分（视为未建立自动发包流程）","conditions":[{"label":"条件 1","value":"workflow 中使用制品上传插件（obs-upload / upload-artifact）"},{"label":"条件 2","value":"仓库命中 openEuler 打包工程清单（包名口径比对）"}],"naCondition":"无，本指标恒有得分。","notes":[]},"definition":{"brief":"衡量仓库是否具备自动化发包流程：workflow 中配置了制品上传插件，或被 openEuler 打包工程收录。","purpose":"自动化发包保证发布过程可重复、可审计，减少人工操作引入的错漏与安全风险。","details":[{"label":"数据来源","value":"workflow 文件扫描 + openEuler 打包工程清单比对（包名口径）"},{"label":"判定条件","value":"workflow 中使用 obs-upload / upload-artifact 制品上传插件，或仓库命中 openEuler 包清单"}],"notes":["openEuler 社区存在独立发包流程，命中其包清单同样视为满足"]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库是否具备自动化发包能力，满足任一即算：workflow 中配置了制品上传插件（obs-upload 或 upload-artifact）；或仓库被收录在 openEuler（Eluermaker）打包工程清单中。","formula":"具备自动化发包能力 = 10 分；未检出 = 0 分（视为未建立自动发包流程）","conditions":[{"label":"条件 1","value":"workflow 中使用制品上传插件（obs-upload / upload-artifact）"},{"label":"条件 2","value":"仓库命中 openEuler 打包工程清单（包名口径比对）"}],"naCondition":"无，本指标恒有得分。","notes":[]},"definition":{"brief":"衡量仓库是否具备自动化发包流程：workflow 中配置了制品上传插件，或被 openEuler 打包工程收录。","purpose":"自动化发包保证发布过程可重复、可审计，减少人工操作引入的错漏与安全风险。","details":[{"label":"数据来源","value":"workflow 文件扫描 + openEuler 打包工程清单比对（包名口径）"},{"label":"判定条件","value":"workflow 中使用 obs-upload / upload-artifact 制品上传插件，或仓库命中 openEuler 包清单"}],"notes":["openEuler 社区存在独立发包流程，命中其包清单同样视为满足"]}}' AS JSON), '$.definition'))
