-- SAST
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查 pre-commit 配置（根目录或 pre-commit/ 目录，两处同时存在则合并）或 workflow 文件中，是否使用了任一静态分析（SAST）工具，不区分语言。","formula":"命中任一工具 = 10 分（多个不加分）；有配置文件但 0 命中 = 0 分","conditions":[{"label":"工具清单","value":"clang-tidy / bandit / eslint / gosec / clippy / spotbugs / gitleaks / luacheck"}],"naCondition":"既没有 pre-commit 配置文件、又没有 workflow 文件时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量仓库是否在 pre-commit 配置或 workflow 中使用静态分析（SAST）工具，不区分语言。","purpose":"静态分析在编码阶段自动发现安全缺陷与代码坏味道，把安全问题左移到提交前，修复成本最低。","details":[{"label":"数据来源","value":"pre-commit 配置与 .gitcode/workflows 文件扫描"},{"label":"工具清单","value":"clang-tidy、bandit、eslint、gosec、clippy、spotbugs、gitleaks、luacheck（8 项）"},{"label":"判定","value":"任一命中即满分（二元判定，多命中不加分）"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查 pre-commit 配置（根目录或 pre-commit/ 目录，两处同时存在则合并）或 workflow 文件中，是否使用了任一静态分析（SAST）工具，不区分语言。","formula":"命中任一工具 = 10 分（多个不加分）；有配置文件但 0 命中 = 0 分","conditions":[{"label":"工具清单","value":"clang-tidy / bandit / eslint / gosec / clippy / spotbugs / gitleaks / luacheck"}],"naCondition":"既没有 pre-commit 配置文件、又没有 workflow 文件时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量仓库是否在 pre-commit 配置或 workflow 中使用静态分析（SAST）工具，不区分语言。","purpose":"静态分析在编码阶段自动发现安全缺陷与代码坏味道，把安全问题左移到提交前，修复成本最低。","details":[{"label":"数据来源","value":"pre-commit 配置与 .gitcode/workflows 文件扫描"},{"label":"工具清单","value":"clang-tidy、bandit、eslint、gosec、clippy、spotbugs、gitleaks、luacheck（8 项）"},{"label":"判定","value":"任一命中即满分（二元判定，多命中不加分）"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'SAST';

-- FUZZING
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库是否开展模糊测试活动：收录于 OSS-Fuzz 官方项目名单、workflow 中配置 ClusterFuzzLite、使用语言原生 fuzz 能力（go test fuzz / libFuzzer / atheris / cargo-fuzz / Jazzer 等），或配置 property-testing。共 17 项判据（2 项非语言 + 7 项引擎型 + 8 项属性测试），检测到的工具数量不影响评分。","formula":"阶梯计分，只取满足的最高档：OSS-Fuzz 或 ClusterFuzzLite = 10 分；语言原生 fuzz = 5 分；property-testing = 3 分；全部未检出 = 0 分。各档相互独立，不存在低档阻断。","conditions":[{"label":"OSS-Fuzz","value":"仓库收录于 OSS-Fuzz 官方项目名单（main_repo 归一化比对）"},{"label":"ClusterFuzzLite","value":"workflow 中引用 / 配置 ClusterFuzzLite"},{"label":"原生 fuzz","value":"go test fuzz、C/C++/Swift libFuzzer、python-atheris、rust cargo-fuzz、java Jazzer"},{"label":"property-testing","value":"Haskell / JS / TS / C# / F# / Erlang / Elixir / Gleam 属性测试框架"}],"naCondition":"无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA。「全部未检出」是有效 0 分，不是 NA。","notes":["口径 = OSSF Scorecard v5.5.0 fuzzing check + property-testing=3 分阶梯扩展（Q-048 答复：8 项属性测试判据都算分）","2026-10-09 起生产数据来自 security_gcheck_scan.py（gcheck 离线扫描批次）"]},"definition":{"brief":"衡量仓库是否开展模糊测试活动：收录于 OSS-Fuzz 官方项目、配置 ClusterFuzzLite、使用语言原生 fuzz 能力，或配置属性测试（property-testing）。","purpose":"模糊测试能自动发现内存破坏、解析崩溃等深度漏洞，是解析器、加解密等高危代码的重要防线。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据），OSS-Fuzz 名单快照比对"},{"label":"判据构成","value":"2 项非语言判据 + 7 项引擎型判据 + 8 项属性测试判据，共 17 项"},{"label":"参考标准","value":"OSSF Scorecard v5.5.0 fuzzing + property-testing 阶梯扩展"}],"notes":["检测到的工具数量不影响评分，只取满足的最高档"]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库是否开展模糊测试活动：收录于 OSS-Fuzz 官方项目名单、workflow 中配置 ClusterFuzzLite、使用语言原生 fuzz 能力（go test fuzz / libFuzzer / atheris / cargo-fuzz / Jazzer 等），或配置 property-testing。共 17 项判据（2 项非语言 + 7 项引擎型 + 8 项属性测试），检测到的工具数量不影响评分。","formula":"阶梯计分，只取满足的最高档：OSS-Fuzz 或 ClusterFuzzLite = 10 分；语言原生 fuzz = 5 分；property-testing = 3 分；全部未检出 = 0 分。各档相互独立，不存在低档阻断。","conditions":[{"label":"OSS-Fuzz","value":"仓库收录于 OSS-Fuzz 官方项目名单（main_repo 归一化比对）"},{"label":"ClusterFuzzLite","value":"workflow 中引用 / 配置 ClusterFuzzLite"},{"label":"原生 fuzz","value":"go test fuzz、C/C++/Swift libFuzzer、python-atheris、rust cargo-fuzz、java Jazzer"},{"label":"property-testing","value":"Haskell / JS / TS / C# / F# / Erlang / Elixir / Gleam 属性测试框架"}],"naCondition":"无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA。「全部未检出」是有效 0 分，不是 NA。","notes":["口径 = OSSF Scorecard v5.5.0 fuzzing check + property-testing=3 分阶梯扩展（Q-048 答复：8 项属性测试判据都算分）","2026-10-09 起生产数据来自 security_gcheck_scan.py（gcheck 离线扫描批次）"]},"definition":{"brief":"衡量仓库是否开展模糊测试活动：收录于 OSS-Fuzz 官方项目、配置 ClusterFuzzLite、使用语言原生 fuzz 能力，或配置属性测试（property-testing）。","purpose":"模糊测试能自动发现内存破坏、解析崩溃等深度漏洞，是解析器、加解密等高危代码的重要防线。","details":[{"label":"数据来源","value":"gcheck 离线扫描批次（2026-10-09 起生产数据），OSS-Fuzz 名单快照比对"},{"label":"判据构成","value":"2 项非语言判据 + 7 项引擎型判据 + 8 项属性测试判据，共 17 项"},{"label":"参考标准","value":"OSSF Scorecard v5.5.0 fuzzing + property-testing 阶梯扩展"}],"notes":["检测到的工具数量不影响评分，只取满足的最高档"]}}' AS JSON), '$.definition'))
WHERE metric_code = 'FUZZING';

-- SECURITY_POLICY
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库是否提供安全政策文档 SECURITY.md（检查 .gitcode/、根目录、docs/ 等位置），并对文档内容做三项检测：漏洞披露信息、联系链接、自由文本说明。","formula":"无 SECURITY.md = 0 分；有 SECURITY.md 时三项独立加分：漏洞披露信息 +1、联系链接 +6、自由文本说明 +3（满分 10）","conditions":[{"label":"漏洞披露信息","value":"文档包含漏洞报告相关说明（report / vulnerability / disclosure / exploit / CVE 等关键词）"},{"label":"联系链接","value":"文档包含邮箱或 URL"},{"label":"自由文本说明","value":"文档包含实质性文本内容"}],"naCondition":"无，本指标恒有得分。","notes":[]},"definition":{"brief":"衡量仓库是否公开了安全策略文档（SECURITY.md），并考察文档质量：漏洞披露说明、联系方式、实质内容三项独立检测。","purpose":"安全策略让安全研究者知道往哪报告漏洞、能期待怎样的响应，是漏洞负责任披露机制的基础设施。","details":[{"label":"数据来源","value":"仓库文件树扫描（.gitcode/、根目录、docs/ 等位置）"},{"label":"检查对象","value":"SECURITY.md 标准命名文件 + 文档内容三项检测"},{"label":"参考标准","value":"对齐 OSSF Scorecard security-policy 思想"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库是否提供安全政策文档 SECURITY.md（检查 .gitcode/、根目录、docs/ 等位置），并对文档内容做三项检测：漏洞披露信息、联系链接、自由文本说明。","formula":"无 SECURITY.md = 0 分；有 SECURITY.md 时三项独立加分：漏洞披露信息 +1、联系链接 +6、自由文本说明 +3（满分 10）","conditions":[{"label":"漏洞披露信息","value":"文档包含漏洞报告相关说明（report / vulnerability / disclosure / exploit / CVE 等关键词）"},{"label":"联系链接","value":"文档包含邮箱或 URL"},{"label":"自由文本说明","value":"文档包含实质性文本内容"}],"naCondition":"无，本指标恒有得分。","notes":[]},"definition":{"brief":"衡量仓库是否公开了安全策略文档（SECURITY.md），并考察文档质量：漏洞披露说明、联系方式、实质内容三项独立检测。","purpose":"安全策略让安全研究者知道往哪报告漏洞、能期待怎样的响应，是漏洞负责任披露机制的基础设施。","details":[{"label":"数据来源","value":"仓库文件树扫描（.gitcode/、根目录、docs/ 等位置）"},{"label":"检查对象","value":"SECURITY.md 标准命名文件 + 文档内容三项检测"},{"label":"参考标准","value":"对齐 OSSF Scorecard security-policy 思想"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'SECURITY_POLICY';

-- VULNS
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查漏洞管理平台中本仓库已超期且未关闭的漏洞，按严重度扣分。已关闭、已拒绝的漏洞不计入。","formula":"得分 = 10 − (致命×10 + 高危×5 + 中危×2 + 低危×1)，最低 0 分","conditions":[{"label":"致命","value":"每个扣 10 分"},{"label":"高危","value":"每个扣 5 分"},{"label":"中危","value":"每个扣 2 分"},{"label":"低危","value":"每个扣 1 分（严重度未标注的按低危计）"}],"naCondition":"漏洞平台未跟踪本仓库时，本指标不参评（不计入总分，不是 0 分）。","notes":["有跟踪且无超期漏洞 = 满分 10 分","超期判定 = 计划修复时间已过且仍未关闭"]},"definition":{"brief":"衡量漏洞管理平台中本仓库存量漏洞的修复及时性：已超期且未关闭的漏洞越多、严重度越高，扣分越多。","purpose":"推动团队在承诺的修复期限内关闭已知漏洞，避免漏洞长期滞留演变成安全债务。","details":[{"label":"数据来源","value":"漏洞管理平台（漏洞单的状态、严重度、计划修复时间）"},{"label":"统计口径","value":"已超期且未关闭的漏洞；已关闭、已拒绝的不计入"},{"label":"超期判定","value":"计划修复时间已过且仍未关闭"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查漏洞管理平台中本仓库已超期且未关闭的漏洞，按严重度扣分。已关闭、已拒绝的漏洞不计入。","formula":"得分 = 10 − (致命×10 + 高危×5 + 中危×2 + 低危×1)，最低 0 分","conditions":[{"label":"致命","value":"每个扣 10 分"},{"label":"高危","value":"每个扣 5 分"},{"label":"中危","value":"每个扣 2 分"},{"label":"低危","value":"每个扣 1 分（严重度未标注的按低危计）"}],"naCondition":"漏洞平台未跟踪本仓库时，本指标不参评（不计入总分，不是 0 分）。","notes":["有跟踪且无超期漏洞 = 满分 10 分","超期判定 = 计划修复时间已过且仍未关闭"]},"definition":{"brief":"衡量漏洞管理平台中本仓库存量漏洞的修复及时性：已超期且未关闭的漏洞越多、严重度越高，扣分越多。","purpose":"推动团队在承诺的修复期限内关闭已知漏洞，避免漏洞长期滞留演变成安全债务。","details":[{"label":"数据来源","value":"漏洞管理平台（漏洞单的状态、严重度、计划修复时间）"},{"label":"统计口径","value":"已超期且未关闭的漏洞；已关闭、已拒绝的不计入"},{"label":"超期判定","value":"计划修复时间已过且仍未关闭"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'VULNS';

-- MAINTAINED
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库近 90 天的维护活跃度 = 默认分支 commit 数 + 新建 issue 数。","formula":"得分 = 10 × (commit 数 + issue 数) / 13，上限 10 分（近 90 天合计 13 个即满分）","conditions":[{"label":"commit","value":"默认分支近 90 天提交数"},{"label":"issue","value":"近 90 天新建 issue 数"}],"naCondition":"仓库已归档、或创建时间不足 90 天（尚在孵化期）时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量仓库近 90 天的维护活跃度：默认分支 commit 数与新建 issue 数合计对照活跃门槛。","purpose":"长期无人维护的仓库意味着缺陷得不到修复、依赖得不到升级，是供应链风险的高发区。","details":[{"label":"数据来源","value":"仓库 commit 日志与 issue 处理记录"},{"label":"统计口径","value":"近 90 天默认分支 commit 数 + 新建 issue 数"},{"label":"参考标准","value":"对齐 OSSF Scorecard maintained 思想"}],"notes":["仓库已归档或创建不足 90 天（孵化期）时不参评"]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查仓库近 90 天的维护活跃度 = 默认分支 commit 数 + 新建 issue 数。","formula":"得分 = 10 × (commit 数 + issue 数) / 13，上限 10 分（近 90 天合计 13 个即满分）","conditions":[{"label":"commit","value":"默认分支近 90 天提交数"},{"label":"issue","value":"近 90 天新建 issue 数"}],"naCondition":"仓库已归档、或创建时间不足 90 天（尚在孵化期）时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量仓库近 90 天的维护活跃度：默认分支 commit 数与新建 issue 数合计对照活跃门槛。","purpose":"长期无人维护的仓库意味着缺陷得不到修复、依赖得不到升级，是供应链风险的高发区。","details":[{"label":"数据来源","value":"仓库 commit 日志与 issue 处理记录"},{"label":"统计口径","value":"近 90 天默认分支 commit 数 + 新建 issue 数"},{"label":"参考标准","value":"对齐 OSSF Scorecard maintained 思想"}],"notes":["仓库已归档或创建不足 90 天（孵化期）时不参评"]}}' AS JSON), '$.definition'))
WHERE metric_code = 'MAINTAINED';

-- CONTRIBUTORS
UPDATE dm_rd_efc_security_metric_detail_conf
SET conf_json = JSON_SET(CAST(conf_json AS JSON),
  '$.rule', JSON_EXTRACT(CAST('{"rule":{"brief":"检查最近 30 次已合入 PR 的作者（剔除机器人）来自多少个不同组织，且这些组织中是否有活跃作者（近 30 次 PR 中个人贡献 ≥ 5 个）。","formula":"得分 = 10 × N / 3，上限 10 分（N = 存在至少 1 名活跃作者的组织个数，3 个即满分）","conditions":[{"label":"活跃作者","value":"近 30 次已合入 PR 中该作者贡献 ≥ 5 个"},{"label":"N 值","value":"存在至少 1 名活跃作者的组织个数"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"近 30 次已合入 PR 为 0 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量仓库贡献者来源组织的多样性：近 30 次已合入 PR 中，活跃作者覆盖的不同组织个数。","purpose":"单一组织依赖意味着 bus factor 风险：一旦该组织退出，项目可能失去维护能力；多组织参与是社区健康度的信号。","details":[{"label":"数据来源","value":"PR 与贡献者组织归属（GitCode）"},{"label":"统计口径","value":"N = 存在至少 1 名活跃作者（近 30 次 PR 中贡献 ≥ 5 个）的组织个数，剔除机器人"},{"label":"计分","value":"N ≥ 3 即满分"}],"notes":[]}}' AS JSON), '$.rule'),
  '$.definition', JSON_EXTRACT(CAST('{"rule":{"brief":"检查最近 30 次已合入 PR 的作者（剔除机器人）来自多少个不同组织，且这些组织中是否有活跃作者（近 30 次 PR 中个人贡献 ≥ 5 个）。","formula":"得分 = 10 × N / 3，上限 10 分（N = 存在至少 1 名活跃作者的组织个数，3 个即满分）","conditions":[{"label":"活跃作者","value":"近 30 次已合入 PR 中该作者贡献 ≥ 5 个"},{"label":"N 值","value":"存在至少 1 名活跃作者的组织个数"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"近 30 次已合入 PR 为 0 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]},"definition":{"brief":"衡量仓库贡献者来源组织的多样性：近 30 次已合入 PR 中，活跃作者覆盖的不同组织个数。","purpose":"单一组织依赖意味着 bus factor 风险：一旦该组织退出，项目可能失去维护能力；多组织参与是社区健康度的信号。","details":[{"label":"数据来源","value":"PR 与贡献者组织归属（GitCode）"},{"label":"统计口径","value":"N = 存在至少 1 名活跃作者（近 30 次 PR 中贡献 ≥ 5 个）的组织个数，剔除机器人"},{"label":"计分","value":"N ≥ 3 即满分"}],"notes":[]}}' AS JSON), '$.definition'))
WHERE metric_code = 'CONTRIBUTORS';
